WITH valid_departments AS (SELECT *, CASE WHEN location IN ('Bangkok', 'Berlin') THEN 'Priority' ELSE 'Other' END AS location_group FROM departments WHERE dept_name NOT IN ('Sales', 'Marketing')), agg AS (SELECT dept_name, COUNT(DISTINCT budget) AS unique_dept_names, MAX(budget) - MIN(budget) AS budget_range FROM valid_departments GROUP BY dept_name) SELECT * FROM agg WHERE unique_dept_names >= 4 ORDER BY dept_name;
